class Solution {
public:
    string removeDuplicateLetters(string s) {
        stack<char> stk;
        vector<int> vis(26,0);
        vector<int> freq(26,0);
        for(auto it:s)
            freq[it-'a']++;
        for(auto it:s)
        {
            freq[it-'a']--;
            if(vis[it-'a'])
                continue;
            while(!stk.empty() and it<stk.top() and freq[stk.top()-'a']!=0)
            {
                char ch=stk.top();
                stk.pop();
                vis[ch-'a']=0;
            }
            stk.push(it);
            vis[it-'a']=1;
        }
        string ans="";
        while(!stk.empty())
        {
            ans+=stk.top();
            stk.pop();
        }
        reverse(ans.begin(),ans.end());
        return ans;
    }
};

class Solution(object):
    def removeDuplicateLetters(self, s):
        """
        :type s: str
        :rtype: str
        """
        all = set(s)
        chrs = sorted(list(all))
        for chr in chrs:
            idx = s.index(chr)
            if set(s[idx:])==all:
                s = s[idx:].replace(chr, '')
                return chr + self.removeDuplicateLetters(s)
        return ''

class Solution(object):
    def removeDuplicateLetters(self, s):
        """
        :type s: str
        :rtype: str
        """
        cnt = collections.Counter(s)
        stack = []
        for c in s:
            if c not in stack:
                while stack and c < stack[-1] and cnt[stack[-1]] > 0:
                    stack.pop()
                stack.append(c)
            cnt[c] -= 1
        return "".join(stack)
